<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
    <title>Gamma Catering - Mobile</title>
    <style>
        :root {
            --primary-bg: #4a0e1c; /* Deep Burgundy */
            --text-white: #ffffff;
            --text-offwhite: #f0f0f0;
            --btn-border: #ffffff;
            --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            --font-script: "Brush Script MT", cursive; /* Fallback for script */
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
            -webkit-tap-highlight-color: transparent;
        }

        body {
            background-color: var(--primary-bg);
            color: var(--text-white);
            font-family: var(--font-sans);
            overflow-x: hidden;
            min-height: 100vh;
            display: flex;
            flex-direction: column;
        }

        /* --- Header / Sticky Elements --- */
        header {
            position: sticky;
            top: 0;
            z-index: 100;
            background-color: var(--primary-bg);
            padding: 16px 20px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            border-bottom: 1px solid rgba(255,255,255,0.05);
        }

        .logo {
            width: 32px;
            height: 32px;
            border: 2px solid white;
            border-radius: 50%;
            position: relative;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .logo::after {
            content: 'G';
            font-weight: bold;
            font-style: italic;
            font-size: 18px;
        }

        .nav-left {
            display: flex;
            align-items: center;
            gap: 20px;
            font-size: 14px;
            font-weight: 600;
            letter-spacing: 0.5px;
        }

        .lang-switch span {
            cursor: pointer;
            opacity: 0.6;
        }
        .lang-switch span.active {
            opacity: 1;
        }

        .enquiry-btn-header {
            border: 1.5px solid var(--btn-border);
            padding: 8px 20px;
            border-radius: 6px;
            text-decoration: none;
            color: white;
            font-size: 12px;
            letter-spacing: 1px;
            transition: all 0.2s ease;
        }

        .enquiry-btn-header:active {
            background-color: rgba(255,255,255,0.1);
            transform: scale(0.98);
        }

        .hamburger {
            width: 24px;
            height: 18px;
            display: flex;
            flex-direction: column;
            justify-content: space-between;
            cursor: pointer;
        }

        .hamburger div {
            width: 100%;
            height: 2px;
            background-color: white;
        }

        /* --- Hero Section --- */
        main {
            flex: 1;
            display: flex;
            flex-direction: column;
            align-items: center;
            padding-top: 40px;
            padding-bottom: 60px;
            position: relative;
        }

        /* The Collage Image Container */
        .hero-collage {
            position: relative;
            width: 280px;
            height: 320px;
            margin-bottom: 40px;
            /* Creating the scattered look with pseudo elements or nested images */
        }

        .collage-img {
            position: absolute;
            box-shadow: 0 10px 30px rgba(0,0,0,0.3);
            object-fit: cover;
            border: 2px solid #fff; /* Slight border to define edges if needed, or just shadow */
        }

        /* Center Image (Main) */
        .img-main {
            width: 180px;
            height: 240px;
            left: 50px;
            top: 40px;
            z-index: 3;
            transform: rotate(-2deg);
            background: url('https://images.unsplash.com/photo-1556910103-1c02745a30bf?ixlib=rb-1.2.1&auto=format&fit=crop&w=400&q=80') no-repeat center/cover;
        }

        /* Left Image */
        .img-left {
            width: 140px;
            height: 160px;
            left: 0;
            top: 80px;
            z-index: 2;
            transform: rotate(-8deg);
            filter: grayscale(100%) contrast(120%);
            background: url('https://images.unsplash.com/photo-1414235077428-338989a2e8c0?ixlib=rb-1.2.1&auto=format&fit=crop&w=400&q=80') no-repeat center/cover;
        }

        /* Right Image */
        .img-right {
            width: 140px;
            height: 170px;
            right: 10px;
            top: 20px;
            z-index: 2;
            transform: rotate(5deg);
            filter: grayscale(100%) contrast(120%);
            background: url('https://images.unsplash.com/photo-1550966871-3ed3cdb51f3a?ixlib=rb-1.2.1&auto=format&fit=crop&w=400&q=80') no-repeat center/cover;
        }

        /* Typography */
        .headline-script {
            font-family: 'Brush Script MT', cursive;
            font-size: 64px;
            line-height: 0.9;
            text-align: center;
            margin-bottom: 30px;
            position: relative;
            z-index: 10;
            /* Simulating the handwritten overlay feel */
            text-shadow: 0 2px 10px rgba(0,0,0,0.3); 
            transform: rotate(-2deg);
        }

        .sub-text {
            text-align: center;
            font-size: 17px;
            line-height: 1.5;
            max-width: 85%;
            margin-bottom: 40px;
            font-weight: 300;
            opacity: 0.95;
        }

        /* --- CTAs --- */
        .cta-group {
            display: flex;
            gap: 15px;
            margin-bottom: auto; /* Pushes footer down if content is short */
        }

        .btn {
            padding: 14px 28px;
            border-radius: 8px;
            font-size: 14px;
            font-weight: 600;
            letter-spacing: 1px;
            text-transform: uppercase;
            text-decoration: none;
            cursor: pointer;
            transition: transform 0.1s ease, background-color 0.2s;
            /* Touch target sizing */
            min-height: 48px;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .btn-outline {
            border: 1.5px solid var(--btn-border);
            color: white;
            background: transparent;
        }

        .btn-solid {
            border: 1.5px solid transparent;
            background-color: white;
            color: var(--primary-bg);
        }

        .btn:active {
            transform: scale(0.96);
            opacity: 0.9;
        }

        /* --- Footer / Floating Action --- */
        .footer-action {
            position: fixed;
            bottom: 25px;
            left: 25px;
            z-index: 90;
            width: 44px;
            height: 44px;
            background: rgba(255,255,255,0.1);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            backdrop-filter: blur(5px);
            border: 1px solid rgba(255,255,255,0.2);
            cursor: pointer;
        }

        .footer-icon {
            width: 24px;
            height: 24px;
            fill: white;
            opacity: 0.7;
        }

        /* Responsive Tweaks for very small screens */
        @media (max-width: 360px) {
            .headline-script { font-size: 52px; }
            .hero-collage { transform: scale(0.9); }
            .sub-text { font-size: 15px; }
        }
    </style>
</head>
<body>

    <!-- Sticky Header -->
    <header>
        <div class="logo" aria-label="Gamma Logo"></div>

        <div class="nav-left">
            <div class="lang-switch">
                <span class="active">DE</span> &nbsp; <span>EN</span>
            </div>
            <a href="#" class="enquiry-btn-header">ENQUIRY</a>
        </div>

        <div class="hamburger" aria-label="Menu">
            <div></div>
            <div></div>
            <div></div>
        </div>
    </header>

    <!-- Main Content -->
    <main>
        <!-- Visual Collage -->
        <section class="hero-collage">
            <div class="collage-img img-left"></div>
            <div class="collage-img img-right"></div>
            <div class="collage-img img-main"></div>

            <!-- Text Overlay on Image Area -->
            <h1 class="headline-script">
                Gamma is a<br>feeling
            </h1>
        </section>

        <!-- Description -->
        <p class="sub-text">
            Switzerland's leading provider of premium catering and experience design.
        </p>

        <!-- Primary CTAs -->
        <nav class="cta-group">
            <a href="#about" class="btn btn-outline">About Us</a>
            <a href="#contact" class="btn btn-solid">Enquiry</a>
        </nav>
    </main>

